31	struct Rgb { double r, g, b; };
32	
33	Rgb parse_hex(const std::string& hex)
34	{
35	    REQUIRE(hex.size() == 7);
36	    REQUIRE(hex[0] == '#');
37	    auto channel = [&](size_t at) { return std::stoi(hex.substr(at, 2), nullptr, 16) / 255.0; };
38	    return {channel(1), channel(3), channel(5)};
39	}
