41	// WCAG 2 relative luminance and contrast ratio.
42	double linear(double c) { return c <= 0.03928 ? c / 12.92 : std::pow((c + 0.055) / 1.055, 2.4); }
43	double luminance(const Rgb& c) { return 0.2126 * linear(c.r) + 0.7152 * linear(c.g) + 0.0722 * linear(c.b); }
44	double contrast(const std::string& a, const std::string& b)
45	{
46	    const double la = luminance(parse_hex(a)), lb = luminance(parse_hex(b));
47	    return (std::max(la, lb) + 0.05) / (std::min(la, lb) + 0.05);
48	}
