66	TEST_CASE("text keeps the documented contrast on every surface", "[brand]")
67	{
68	    const json tokens = load_tokens();
69	    for (const char* mode : {"light", "dark"}) {
70	        const json& s = tokens.at("semantic").at(mode);
71	        for (const char* surface : {"canvas", "subtle", "raised", "selected"}) {
72	            const std::string bg = s.at("surface").at(surface);
