127	TEST_CASE("dark mode is a remapping, not a copy of light mode", "[brand]")
128	{
129	    const json tokens = load_tokens();
130	    const json& light = tokens.at("semantic").at("light");
131	    const json& dark  = tokens.at("semantic").at("dark");
132	    CHECK(light.at("surface").at("canvas") != dark.at("surface").at("canvas"));
133	    CHECK(light.at("action").at("primary") != dark.at("action").at("primary"));
134	    // The same token names exist in both modes so a component can switch by
135	    // mode alone: a token added to one mode must be added to the other.
136	    auto require_mirror = [](const json& from, const char* from_mode, const json& to, const char* to_mode) {
137	        for (const auto& [group, values] : from.items())
138	            for (const auto& [name, value] : values.items()) {
139	                INFO("semantic." << from_mode << "." << group << "." << name
140	                     << " has no counterpart in semantic." << to_mode);
141	                CHECK((to.contains(group) && to.at(group).contains(name)));
142	            }
143	    };
144	    require_mirror(light, "light", dark, "dark");
145	    require_mirror(dark, "dark", light, "light");
146	}
