148	// The scale cases pin the tables in agent-docs/jusprin/design-system.md.
149	// Each one names the offending key so a wrong edit is a one-line fix.
150	
151	template <typename T>
152	void require_exact_table(const json& actual, const std::map<std::string, T>& expected, const std::string& path)
153	{
154	    for (const auto& [key, value] : expected) {
155	        INFO(path << "." << key << " expected " << value);
156	        REQUIRE(actual.contains(key));
157	        CHECK(actual.at(key) == json(value));
158	    }
159	    for (const auto& [key, value] : actual.items()) {
160	        INFO(path << "." << key << " is not part of the scale");
161	        CHECK(expected.count(key) == 1);
162	    }
163	}
