1	// Applies the repository's design tokens as CSS custom properties.
2	// resources/jusprin/ui/design-tokens.json is the implementation source of
3	// truth; the stylesheet must use var(--...) rather than literal colors,
4	// radii, or type metrics. styles.test.ts enforces that on the stylesheet.
5	
6	import tokens from '@resources/jusprin/ui/design-tokens.json';
7	import type { Appearance } from './bridge/protocol';
8	
9	type TokenGroup = Record<string, string>;
10	type SemanticMode = Record<string, TokenGroup>;
11	
12	interface TypeRole {
13	  size: number;
14	  lineHeight: number;
15	  weight: number;
16	}
17	
18	interface ButtonRecipe {
19	  paddingX?: number;
20	  paddingY?: number;
21	}
22	
23	interface StaticTokens {
24	  dimension: { radius: Record<string, number> };
25	  typography: {
26	    ui: { family: string; cssFallback: string };
27	    technical: { cssFamily: string };
28	    roles: Record<string, TypeRole>;
29	  };
30	  component: { button: Record<string, ButtonRecipe> };
31	}
32	
33	// The three roles that also exist in the technical (monospace) face: Figma's
34	// Mono Body, Mono Label, and Mono Metadata share the UI roles' metrics.
35	const monoRoles = ['body', 'label', 'metadata'] as const;
36	
37	function fontShorthand(role: TypeRole, family: string): string {
38	  return `${role.weight} ${role.size}px/${role.lineHeight}px ${family}`;
39	}
40	
41	// The token file names roles in camelCase (pageTitle, bodyBold); CSS custom
42	// properties take the kebab-case form (--font-page-title, --font-body-bold).
43	function kebab(name: string): string {
44	  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
45	}
46	
47	// Every --font-* and --button-* variable applyStaticTokens writes, so a test
48	// can check that the stylesheet only asks for variables that exist.
49	export function staticVariableNames(): string[] {
50	  const { typography, component } = tokens as unknown as StaticTokens;
51	  return [
52	    ...Object.keys(typography.roles).map((name) => `--font-${kebab(name)}`),
53	    ...monoRoles.map((name) => `--font-mono-${kebab(name)}`),
54	    ...Object.entries(component.button)
55	      .filter(([, recipe]) => recipe.paddingX !== undefined && recipe.paddingY !== undefined)
56	      .map(([name]) => `--button-${kebab(name)}-padding`),
57	  ];
58	}
59	
60	// Colors depend on the appearance; everything below does not, so it is
61	// written once at startup:
62	//   --radius-<name>       e.g. --radius-container: 8px
63	//   --font-<role>         full `font` shorthand in the UI face, kebab-case
64	//   --font-mono-<role>    the same metrics in the technical face
65	//   --button-<recipe>-padding  "<y>px <x>px" from component.button; control
66	//                         padding follows the recipes, not the spacing scale
67	export function applyStaticTokens(): void {
68	  const { dimension, typography, component } = tokens as unknown as StaticTokens;
69	  const root = document.documentElement;
70	  for (const [name, value] of Object.entries(dimension.radius)) {
71	    root.style.setProperty(`--radius-${name}`, `${value}px`);
72	  }
73	  const uiFamily = `'${typography.ui.family}', ${typography.ui.cssFallback}`;
74	  for (const [name, role] of Object.entries(typography.roles)) {
75	    root.style.setProperty(`--font-${kebab(name)}`, fontShorthand(role, uiFamily));
76	  }
77	  for (const name of monoRoles) {
78	    const role = typography.roles[name];
79	    root.style.setProperty(`--font-mono-${kebab(name)}`, fontShorthand(role, typography.technical.cssFamily));
80	  }
81	  for (const [name, recipe] of Object.entries(component.button)) {
82	    if (recipe.paddingX === undefined || recipe.paddingY === undefined) continue;
83	    root.style.setProperty(`--button-${kebab(name)}-padding`, `${recipe.paddingY}px ${recipe.paddingX}px`);
84	  }
85	}
86	
87	export function applyAppearance(appearance: Appearance): void {
88	  const semantic = (tokens as { semantic: Record<string, SemanticMode> }).semantic;
89	  const mode = semantic[appearance] ?? semantic.light;
90	  const root = document.documentElement;
91	  for (const [group, values] of Object.entries(mode)) {
92	    for (const [name, value] of Object.entries(values)) {
93	      if (typeof value === 'string') root.style.setProperty(`--${group}-${name}`, value);
94	    }
95	  }
96	  root.dataset.appearance = appearance;
97	}
