16	wxColour parse_color(const nlohmann::json& tokens, const char* group, const char* name)
17	{
18	    const nlohmann::json& value = tokens.at(group).at(name);
19	    wxColour color(wxString::FromUTF8(value.get<std::string>()));
20	    if (!color.IsOk())
21	        throw std::runtime_error(std::string("design token ") + group + "." + name + " is not a valid color");
22	    return color;
23	}
