56	// A DIP value or a font weight: the token file promises whole numbers, so
57	// anything else is a malformed file rather than something to round.
58	int parse_int(const nlohmann::json& group, const std::string& path, const char* name)
59	{
60	    const nlohmann::json& value = group.at(name);
61	    if (!value.is_number_integer())
62	        throw std::runtime_error("design token " + path + "." + name + " is not a whole number");
63	    return value.get<int>();
64	}
