66	TextRole parse_text_role(const nlohmann::json& recipe, const std::string& path)
67	{
68	    const std::string name = recipe.at("textRole").get<std::string>();
69	    if (name == "pageTitle") return TextRole::PageTitle;
70	    if (name == "section")   return TextRole::Section;
71	    if (name == "body")      return TextRole::Body;
72	    if (name == "bodyBold")  return TextRole::BodyBold;
73	    if (name == "label")     return TextRole::Label;
74	    if (name == "labelBold") return TextRole::LabelBold;
75	    if (name == "metadata")  return TextRole::Metadata;
76	    throw std::runtime_error("design token " + path + ".textRole names an unknown role: " + name);
77	}
