79	TypeStyle parse_type_style(const nlohmann::json& roles, const char* name)
80	{
81	    const std::string path = std::string("typography.roles.") + name;
82	    const nlohmann::json& role = roles.at(name);
83	    TypeStyle style;
84	    style.size        = parse_int(role, path, "size");
85	    style.line_height = parse_int(role, path, "lineHeight");
86	    style.weight      = parse_int(role, path, "weight");
87	    if (style.weight != 400 && style.weight != 700)
88	        throw std::runtime_error("design token " + path + ".weight must be 400 or 700");
89	    return style;
90	}
