99	    b.compact.padding_y = parse_int(compact, "component.button.compact", "paddingY");
100	    b.compact.radius    = parse_int(compact, "component.button.compact", "radius");
101	    b.compact.text_role = parse_text_role(compact, "component.button.compact");
102	
103	    const nlohmann::json& window = buttons.at("window");
104	    b.window.min_width = parse_int(window, "component.button.window", "minWidth");
105	    b.window.height    = parse_int(window, "component.button.window", "height");
106	    b.window.radius    = parse_int(window, "component.button.window", "radius");
107	    b.window.text_role = parse_text_role(window, "component.button.window");
108	
109	    const nlohmann::json& choice = buttons.at("choice");
110	    b.choice.min_width = parse_int(choice, "component.button.choice", "minWidth");
111	    b.choice.height    = parse_int(choice, "component.button.choice", "height");
112	    b.choice.padding_x = parse_int(choice, "component.button.choice", "paddingX");
113	    b.choice.padding_y = parse_int(choice, "component.button.choice", "paddingY");
114	    b.choice.radius    = parse_int(choice, "component.button.choice", "radius");
115	    b.choice.text_role = parse_text_role(choice, "component.button.choice");
116	
117	    const nlohmann::json& parameter = buttons.at("parameter");
118	    b.parameter.width     = parse_int(parameter, "component.button.parameter", "width");
119	    b.parameter.height    = parse_int(parameter, "component.button.parameter", "height");
120	    b.parameter.radius    = parse_int(parameter, "component.button.parameter", "radius");
121	    b.parameter.text_role = parse_text_role(parameter, "component.button.parameter");
122	
123	    const nlohmann::json& icon = buttons.at("icon");
124	    b.icon.width     = parse_int(icon, "component.button.icon", "width");
125	    b.icon.height    = parse_int(icon, "component.button.icon", "height");
126	    b.icon.icon_size = parse_int(icon, "component.button.icon", "iconSize");
127	    b.icon.radius    = parse_int(icon, "component.button.icon", "radius");
128	
129	    const nlohmann::json& expanded = buttons.at("expanded");
130	    b.expanded.min_height = parse_int(expanded, "component.button.expanded", "minHeight");
131	    b.expanded.padding_x  = parse_int(expanded, "component.button.expanded", "paddingX");
132	    b.expanded.padding_y  = parse_int(expanded, "component.button.expanded", "paddingY");
133	    b.expanded.radius     = parse_int(expanded, "component.button.expanded", "radius");
134	    b.expanded.text_role  = parse_text_role(expanded, "component.button.expanded");
135	    return b;
136	}
