192	ShellTheme ShellTheme::load_from_resources()
193	{
194	    const boost::filesystem::path path = boost::filesystem::path(resources_dir()) / "jusprin" / "ui" / "design-tokens.json";
195	    std::ifstream file(path.string());
196	    if (!file.is_open())
197	        throw std::runtime_error("design token file is missing: " + path.string());
198	
199	    try {
200	        const nlohmann::json tokens = nlohmann::json::parse(file);
201	        ShellTheme theme;
202	        theme.m_light   = parse_palette(tokens.at("semantic").at("light"));
203	        theme.m_dark    = parse_palette(tokens.at("semantic").at("dark"));
204	        theme.m_metrics = parse_metrics(tokens);
205	
206	        const nlohmann::json& roles = tokens.at("typography").at("roles");
207	        theme.m_type_styles[size_t(TextRole::PageTitle)] = parse_type_style(roles, "pageTitle");
208	        theme.m_type_styles[size_t(TextRole::Section)]   = parse_type_style(roles, "section");
209	        theme.m_type_styles[size_t(TextRole::Body)]      = parse_type_style(roles, "body");
210	        theme.m_type_styles[size_t(TextRole::BodyBold)]  = parse_type_style(roles, "bodyBold");
211	        theme.m_type_styles[size_t(TextRole::Label)]     = parse_type_style(roles, "label");
212	        theme.m_type_styles[size_t(TextRole::LabelBold)] = parse_type_style(roles, "labelBold");
213	        theme.m_type_styles[size_t(TextRole::Metadata)]  = parse_type_style(roles, "metadata");
214	        return theme;
215	    } catch (const nlohmann::json::exception& error) {
216	        throw std::runtime_error(std::string("design token file could not be parsed: ") + error.what());
217	    }
218	}
