220	const wxFont& ShellTheme::font(TextRole role) const
221	{
222	    wxFont& font = m_fonts[size_t(role)];
223	    if (font.IsOk())
224	        return font;
225	    const TypeStyle& style = type_style(role);
226	    font = Label::sysFont(style.size, style.weight == 700);
227	#ifndef __APPLE__
228	    // The role sizes are DIP. A point is a DIP on macOS, so sysFont renders
229	    // the token exactly there; elsewhere wx resolves points at 96 dpi and
230	    // sysFont's integer 4/5 truncation lands 14 on 15 px and 10 on 11 px.
231	    // Restating the size as exact points keeps the face and weight sysFont
232	    // chose and makes the em `size` px at 96 dpi, scaled by the window DPI.
233	    font.SetFractionalPointSize(style.size * 72.0 / 96.0);
234	#endif
235	    return font;
236	}
237	
238	const wxFont& ShellTheme::mono_font(TextRole role) const
239	{
240	    wxFont& font = m_mono_fonts[size_t(role)];
241	    if (font.IsOk())
242	        return font;
243	    // Sized from the built role font rather than the raw token so it follows
244	    // the same platform point-size correction font() applies.
245	    font = wxFont(wxFontInfo(this->font(role).GetFractionalPointSize()).Family(wxFONTFAMILY_TELETYPE));
246	    return font;
247	}
